SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ARAP ALFABESİ (س - ي ARASI HARFLER) VE YAZILIŞLARI</text>\n  <rect x="25" y="55" width="200" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Dişli ve Boğaz Harfleri</text>\n  <text x="125" y="115" text-anchor="middle" font-size="18" fill="#1e3a8a">س - ش - ص - ض</text>\n  <text x="125" y="145" text-anchor="middle" font-size="12" fill="#334155">Sin, Şın, Sad, Dad</text>\n  <text x="125" y="175" text-anchor="middle" font-size="11" fill="#475569">Sad ve Dad kalın seslidir.</text>\n  <text x="125" y="205" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">سَمَك (Balık) - شَمْس (Güneş)</text>\n  <rect x="250" y="55" width="200" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Peltek ve Boğaz Harfleri</text>\n  <text x="350" y="115" text-anchor="middle" font-size="18" fill="#14532d">ط - ظ - ع - غ</text>\n  <text x="350" y="145" text-anchor="middle" font-size="12" fill="#334155">Tı, Zı, Ayn, Gayn</text>\n  <text x="350" y="175" text-anchor="middle" font-size="11" fill="#475569">Zı peltek ve kalın okunur.</text>\n  <text x="350" y="205" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">طَالِب (Öğrenci) - عَيْن (Göz)</text>\n  <rect x="475" y="55" width="200" height="180" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Dudak ve Çıkış Harfleri</text>\n  <text x="575" y="115" text-anchor="middle" font-size="18" fill="#713f12">ف - ق - ك - ل - م - ن - هـ - و - ي</text>\n  <text x="575" y="145" text-anchor="middle" font-size="12" fill="#334155">Fe, Kaf, Kef, Lam, Mim, Nun, He, Vav, Ye</text>\n  <text x="575" y="175" text-anchor="middle" font-size="11" fill="#475569">Vav kendinden sonraya birleşmez.</text>\n  <text x="575" y="205" text-anchor="middle" font-size="11" font-weight="bold" fill="#ca8a04">قَلَم (Kalem) - كِتَاب (Kitap)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SINIF İÇİ YÖNERGELER (ERİL VE DİŞİL KULLANIM)</text>\n  <rect x="30" y="55" width="305" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">Erkek Öğrenciye Hitap (Müzekker)</text>\n  <text x="60" y="110" font-size="13" font-weight="bold" fill="#1e3a8a">• قُمْ (Kum):</text><text x="160" y="110" font-size="12" fill="#334155">Ayağa kalk!</text>\n  <text x="60" y="140" font-size="13" font-weight="bold" fill="#1e3a8a">• اِجْلِسْ (İclis):</text><text x="160" y="140" font-size="12" fill="#334155">Otur!</text>\n  <text x="60" y="170" font-size="13" font-weight="bold" fill="#1e3a8a">• اِقْرَأْ (İkra\'):</text><text x="160" y="170" font-size="12" fill="#334155">Oku!</text>\n  <text x="60" y="200" font-size="13" font-weight="bold" fill="#1e3a8a">• اُكْتُبْ (Üktüb):</text><text x="160" y="200" font-size="12" fill="#334155">Yaz!</text>\n  <rect x="365" y="55" width="305" height="180" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="517" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#be185d">Kız Öğrenciye Hitap (Müennes)</text>\n  <text x="395" y="110" font-size="13" font-weight="bold" fill="#9d174d">• قُومِي (Kûmî):</text><text x="500" y="110" font-size="12" fill="#334155">Ayağa kalk!</text>\n  <text x="395" y="140" font-size="13" font-weight="bold" fill="#9d174d">• اِجْلِسِي (İclisî):</text><text x="500" y="140" font-size="12" fill="#334155">Otur!</text>\n  <text x="395" y="170" font-size="13" font-weight="bold" fill="#9d174d">• اِقْرَئِي (İkra\'î):</text><text x="500" y="170" font-size="12" fill="#334155">Oku!</text>\n  <text x="395" y="200" font-size="13" font-weight="bold" fill="#9d174d">• اُكْتُبِي (Üktübî):</text><text x="500" y="200" font-size="12" fill="#334155">Yaz!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSLAM\'DA İLETİŞİM ADABI VE VECİZ SÖZ</text>\n  <rect x="50" y="60" width="600" height="85" rx="8" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="350" y="95" text-anchor="middle" font-size="20" font-weight="bold" fill="#854d0e">«اَلسَّلَامُ قَبْلَ الْكَلَامِ»</text>\n  <text x="350" y="125" text-anchor="middle" font-size="14" fill="#a16207">"Selam, kelamdan (konuşmadan) öncedir." (Hadis-i Şerif)</text>\n  <rect x="50" y="160" width="180" height="75" rx="8" fill="#f1f5f9" stroke="#94a3b8"/>\n  <text x="140" y="185" text-anchor="middle" font-size="13" font-weight="bold" fill="#0f172a">مَعَ السَّلَامَةِ</text>\n  <text x="140" y="210" text-anchor="middle" font-size="12" fill="#475569">Selametle / Güle güle</text>\n  <rect x="260" y="160" width="180" height="75" rx="8" fill="#f1f5f9" stroke="#94a3b8"/>\n  <text x="350" y="185" text-anchor="middle" font-size="13" font-weight="bold" fill="#0f172a">إِلَى اللِّقَاءِ</text>\n  <text x="350" y="210" text-anchor="middle" font-size="12" fill="#475569">Görüşmek üzere</text>\n  <rect x="470" y="160" width="180" height="75" rx="8" fill="#f1f5f9" stroke="#94a3b8"/>\n  <text x="560" y="185" text-anchor="middle" font-size="13" font-weight="bold" fill="#0f172a">فِي أَمَانِ اللهِ</text>\n  <text x="560" y="210" text-anchor="middle" font-size="12" fill="#475569">Allah\'a emanet ol</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
